 rows=[r for r in cs if r['label']==label];ref[label]={'N':len(rows),'features':{n:{'p10':float(np.percentile([float(r[n]) for r in rows],10)),'median':float(np.median([float(r[n]) for r in rows])),'p90':float(np.percentile([float(r[n]) for r in rows],90))} for n in names} if rows else {}}
